	public void speed(PrintWriter print_writer, MatchAllData match) throws IOException, InterruptedException {
//		if (match.getMatch().getCurrent_speed() != null && !match.getMatch().getCurrent_speed().isEmpty()) {
//			print_writer.println(
//					"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BowlerGrp$Section3$Section3All$BallSpeed$img_Text$txt_Data1*GEOM*TEXT SET "
//							+ "BALL SPEED - " + "\0");
//			print_writer.println(
//					"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BowlerGrp$Section3$Section3All$BallSpeed$img_Text$txt_Data2*GEOM*TEXT SET "
//							+ match.getMatch().getCurrent_speed() + " KPH" + "\0");
//			processAnimation(print_writer, "Section3$BallSpeedIn", "START", broadcaster);
//			infobar.setLast_speed_value(match.getMatch().getCurrent_speed());
//			for (Inning inn : match.getMatch().getInning()) {
//				if (inn.getIsCurrentInning().equalsIgnoreCase(CricketUtil.YES)) {
//					infobar.setLast_ball_value(String.valueOf(inn.getTotalBalls()));
//					infobar.setLast_wide_value(String.valueOf(inn.getTotalWides()));
//					infobar.setLast_noball_value(String.valueOf(inn.getTotalNoBalls()));
//				}
//			}
//		}
		
		String text_to_return = "";
		int lineIndex1 = 1;
		boolean found1 = false;
		BufferedReader br = new BufferedReader(
				new FileReader(CricketUtil.CRICKET_DIRECTORY + "Speed/SPEED.txt"));

		while ((text_to_return = br.readLine()) != null) {
			if (lineIndex1 == 1) {
				print_writer.println(
						"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BowlerGrp$Section3$Section3All$BallSpeed$img_Text$txt_Data2*GEOM*TEXT SET "
								+ text_to_return + " KPH" + "\0");
				found1 = true;
				break;
			}
			lineIndex1++;
		}
		if (!found1) {
			// System.out.println("Line Not There");
		}
		
		print_writer.println(
				"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BowlerGrp$Section3$Section3All$BallSpeed$img_Text$txt_Data1*GEOM*TEXT SET "
						+ "BALL SPEED - " + "\0");
		
		processAnimation(print_writer, "Section3$BallSpeedIn", "START", broadcaster);
		infobar.setLast_speed_value(match.getMatch().getCurrent_speed());
		for (Inning inn : match.getMatch().getInning()) {
			if (inn.getIsCurrentInning().equalsIgnoreCase(CricketUtil.YES)) {
				infobar.setLast_ball_value(String.valueOf(inn.getTotalBalls()));
				infobar.setLast_wide_value(String.valueOf(inn.getTotalWides()));
				infobar.setLast_noball_value(String.valueOf(inn.getTotalNoBalls()));
			}
		}
	}

	public void showWinner(Infobar infobar, PrintWriter print_writer, MatchAllData match) throws InterruptedException {
		if (CricketFunctions.GetTargetData(match).getRemaningRuns() == 0 || CricketFunctions.getWicketsLeft(match, 2) <= 0
				|| CricketFunctions.GetTargetData(match).getRemaningBall() == 0) {

			if (infobar.getLast_full_section() != null && !infobar.getLast_full_section().trim().isEmpty()) {
				switch (infobar.getLast_full_section().toUpperCase()) {
				case "TIMELINE":
					processAnimation(print_writer, "Section5$TimeLineOut", "START", broadcaster);
					break;
				case "FREETEXT":  case "DLS_B_BY_B": case "DLS_O_BY_O":
					processAnimation(print_writer, "Section5$FreeTextOut", "START", broadcaster);
					break;
				}
				TimeUnit.MILLISECONDS.sleep(200);
				processAnimation(print_writer, "Section5$Section5Out", "START", broadcaster);
				processAnimation(print_writer, "Section4$Section4In", "START", broadcaster);
				TimeUnit.MILLISECONDS.sleep(200);
				if (match.getSetup().getMatchType().equalsIgnoreCase(CricketUtil.SUPER_OVER)) {
					if (CricketFunctions.GetTargetData(match).getRemaningRuns() == 1 && (CricketFunctions.GetTargetData(match).getRemaningBall() <= 0 || 
							CricketFunctions.getWicketsLeft(match,2) <= 0)) {
						print_writer.println("-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$FreeText$txt_Head*GEOM*TEXT SET "
								+ "SUPER OVER TIED" + "\0");
					}
					else {
						if (CricketFunctions.GetTargetData(match).getRemaningRuns() == 0) {
							print_writer.println("-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$FreeText$txt_Head*GEOM*TEXT SET "
										+ match.getMatch().getInning().get(1).getBatting_team().getTeamName1()+ " WIN\nTHE SUPER OVER" + "\0");
						} else if (CricketFunctions.GetTargetData(match).getRemaningBall() == 0 || CricketFunctions.getWicketsLeft(match, 2) <= 0) {
							print_writer.println("-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$FreeText$txt_Head*GEOM*TEXT SET "
									+ match.getMatch().getInning().get(1).getBowling_team().getTeamName1() + " WIN\nTHE SUPER OVER" + "\0");
						} 
					}
				} else {
					print_writer.println("-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$FreeText$txt_Head*GEOM*TEXT SET "
							+ CricketFunctions.GenerateMatchSummaryStatus(2, match, CricketUtil.FULL, "|",broadcaster,true).getTargetOrResult()
											.toUpperCase().replace("WIN", "WIN\n")+ "\0");
				}

				processAnimation(print_writer, "Section4$FreeTextIn", "START", broadcaster);

				infobar.setShow_winner(true);
			} else if (infobar.getLast_bottom_right_section() != null
					&& !infobar.getLast_bottom_right_section().trim().isEmpty()) {

				switch (infobar.getLast_bottom_right_section().toUpperCase()) {
				case "EQUATION":
					processAnimation(print_writer, "Section4$EquationOut", "START", broadcaster);
					break;
				case "PROJECTED":
					processAnimation(print_writer, "Section4$ProjectedScoreOut", "START", broadcaster);
					break;
				case CricketUtil.COMPARE:
					processAnimation(print_writer, "Section4$AtThisStageOut", "START", broadcaster);
					break;
				case CricketUtil.DOT:
					processAnimation(print_writer, "Section4$DotBallsOut", "START", broadcaster);
					break;
				case CricketUtil.FOUR:case "THIS_MATCH_FOURS": case "TOURNAMENT_FOURS":
					processAnimation(print_writer, "Section4$TournamentFoursOut", "START", broadcaster);
					break;
				case CricketUtil.SIX:case "THIS_MATCH_SIXES": case "TOURNAMENT_SIXES":
					processAnimation(print_writer, "Section4$TournamentSixesOut", "START", broadcaster);
					break;
				case CricketUtil.BOUNDARY:
					processAnimation(print_writer, "Section4$BallsSinceOut", "START", broadcaster);
					break;
				case "BOUNDARIES":
					processAnimation(print_writer, "Section4$InningsBoundariesOut", "START", broadcaster);
					break;
				case "LAST_WICKET":
					processAnimation(print_writer, "Section4$LastWicketOut", "START", broadcaster);
					break;
				case "STATISTICS":
					processAnimation(print_writer, "Section4$FreeTextOut", "START", broadcaster);
					break;
				case "EXTRAS":
					processAnimation(print_writer, "Section4$FreeTextOut", "START", broadcaster);
					break;
				case "REVIEW":
					processAnimation(print_writer, "Section4$ReviewOut", "START", broadcaster);
					break;
				}

				TimeUnit.MILLISECONDS.sleep(200);
				if (match.getSetup().getMatchType().equalsIgnoreCase(CricketUtil.SUPER_OVER)) {
					if (CricketFunctions.GetTargetData(match).getRemaningRuns() == 1 && (CricketFunctions.GetTargetData(match).getRemaningBall() <= 0 || 
							CricketFunctions.getWicketsLeft(match,2) <= 0)) {
						print_writer.println("-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$FreeText$txt_Head*GEOM*TEXT SET "
								+ "SUPER OVER TIED" + "\0");
					}
					else {
						if (CricketFunctions.GetTargetData(match).getRemaningRuns() == 0) {
							print_writer.println("-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$FreeText$txt_Head*GEOM*TEXT SET "
										+ match.getMatch().getInning().get(1).getBatting_team().getTeamName1()+ " WIN\nTHE SUPER OVER" + "\0");
						} else if (CricketFunctions.GetTargetData(match).getRemaningBall() == 0 || CricketFunctions.getWicketsLeft(match, 2) <= 0) {
							print_writer.println("-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$FreeText$txt_Head*GEOM*TEXT SET "
									+ match.getMatch().getInning().get(1).getBowling_team().getTeamName1() + " WIN\nTHE SUPER OVER" + "\0");
						} 
					}
				} else {
					print_writer.println("-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$FreeText$txt_Head*GEOM*TEXT SET "
							+ CricketFunctions.GenerateMatchSummaryStatus(2, match, CricketUtil.FULL, "|",broadcaster,true).getTargetOrResult().toUpperCase().replace("WIN", "WIN\n")+ "\0");
				}

				processAnimation(print_writer, "Section4$FreeTextIn", "START", broadcaster);
				infobar.setShow_winner(true);
			} else if (infobar.getLast_bottom_right_bottom_section() != null
					&& !infobar.getLast_bottom_right_bottom_section().trim().isEmpty()) { // Normal change on

				processAnimation(print_writer, "Section4$Section4In", "START", broadcaster);
				TimeUnit.MILLISECONDS.sleep(400);
				processAnimation(print_writer, "BowlerOut", "START", broadcaster);
				TimeUnit.MILLISECONDS.sleep(200);
				switch (infobar.getLast_bottom_right_bottom_section().toUpperCase()) {
				case CricketUtil.OVER:
					if (CricketFunctions.getEventsText(CricketUtil.OVER, infobar.getPlayer_id(), ",",
							match.getEventFile().getEvents(), 0).split(",").length <= 9) {
						processAnimation(print_writer, "Section3$ThisOverOut", "START", broadcaster);
					} else {
						processAnimation(print_writer, "Section3$FreeTextOut", "START", broadcaster);
					}
					break;
				case "ECONOMY":
					processAnimation(print_writer, "Section3$EconomyOut", "START", broadcaster);
					break;
				case "BOWLINGEND":
					processAnimation(print_writer, "Section3$BowlingEndOut", "START", broadcaster);
					break;
				case "EXTRAS":
					processAnimation(print_writer, "Section3$ExtrasOut", "START", broadcaster);
					break;
				}

				TimeUnit.MILLISECONDS.sleep(200);
				if (match.getSetup().getMatchType().equalsIgnoreCase(CricketUtil.SUPER_OVER)) {
					if (CricketFunctions.GetTargetData(match).getRemaningRuns() == 1 && (CricketFunctions.GetTargetData(match).getRemaningBall() <= 0 || 
							CricketFunctions.getWicketsLeft(match,2) <= 0)) {
						print_writer.println("-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$FreeText$txt_Head*GEOM*TEXT SET "
								+ "SUPER OVER TIED" + "\0");
					}
					else {
						if (CricketFunctions.GetTargetData(match).getRemaningRuns() == 0) {
							print_writer.println("-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$FreeText$txt_Head*GEOM*TEXT SET "
										+ match.getMatch().getInning().get(1).getBatting_team().getTeamName1()+ " WIN\nTHE SUPER OVER" + "\0");
						} else if (CricketFunctions.GetTargetData(match).getRemaningBall() == 0 || CricketFunctions.getWicketsLeft(match, 2) <= 0) {
							print_writer.println("-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$FreeText$txt_Head*GEOM*TEXT SET "
									+ match.getMatch().getInning().get(1).getBowling_team().getTeamName1() + " WIN\nTHE SUPER OVER" + "\0");
						} 
					}
				} else {
					print_writer
							.println("-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$FreeText$txt_Head*GEOM*TEXT SET "
									+ CricketFunctions
											.GenerateMatchSummaryStatus(2, match, CricketUtil.FULL, "|",broadcaster,true).getTargetOrResult()
											.toUpperCase().replace("WIN", "WIN\n")
									+ "\0");
				}

				processAnimation(print_writer, "Section4$FreeTextIn", "START", broadcaster);
				infobar.setShow_winner(true);
			}

			infobar.setLast_full_section("");
			infobar.setFull_section("");
			infobar.setBottom_right_bottom_section("");
			infobar.setLast_bottom_right_bottom_section("");
			infobar.setLast_bottom_right_top_section("");
			infobar.setBottom_right_top_section("");
			infobar.setBottom_right_section("");
			infobar.setLast_bottom_right_section("");

			infobar.setLast_bottom_right_section("EQUATION");
		}
	}
	
	public Object graphicOptions(String whatToProcess, MatchAllData match, CricketService cricketService, List<MatchAllData> tournament_matches, List<PrintWriter> print_writer, 
			List<Statistics> statistics, List<Tournament> past_tournament_stats, List<HeadToHeadPlayer> head_to_head)throws InterruptedException, IOException {
		
		switch(whatToProcess) {
		case "BUG_GRAPHICS-OPTIONS": case "HOWOUT_GRAPHICS-OPTIONS": case "BATSMANSTATS_GRAPHICS-OPTIONS": case "BOWLERSTATS_GRAPHICS-OPTIONS":
		case "NAMESUPER_PLAYER_GRAPHICS-OPTIONS": case "L3PLAYERPROFILE_GRAPHICS-OPTIONS": case "PLAYERPROFILE_GRAPHICS-OPTIONS": case "BOTTOMLEFT_GRAPHICS-OPTIONS":
		case "BOTTOMRIGHT_GRAPHICS-OPTIONS": case "INFOBAR_GRAPHICS-OPTIONS": case "COMPARISION-GRAPHICS-OPTIONS": case "BOTTOM_GRAPHICS-OPTIONS":
		case "ANIMATE_PLAYINGXI-OPTIONS": case "PROJECTED_GRAPHICS-OPTIONS": case "TARGET_GRAPHICS-OPTIONS": case "PLAYERSUMMARY_GRAPHICS-OPTIONS":
		case "BUG_DISMISSAL_GRAPHICS-OPTIONS": case "TOP_GRAPHICS-OPTIONS": case "BUG_BOWLER_GRAPHICS-OPTIONS": case "HOWOUT_WITHOUT_FIELDER_GRAPHICS-OPTIONS":
		case "BOWLERDETAILS_GRAPHICS-OPTIONS": case "NEXTTOBAT_GRAPHICS-OPTIONS": case "BOWLERSUMMARY_GRAPHICS-OPTIONS": case "LANDMARK_GRAPHICS-OPTIONS":
		case "EQUATION_GRAPHICS-OPTIONS": case "POSITION_LANDMARK_GRAPHICS-OPTIONS": case "BATSMAN_THIS_MATCH_GRAPHICS-OPTIONS": case "BOWLER_THIS_MATCH_GRAPHICS-OPTIONS":
		case "PLAYERS_GRAPHICS-OPTIONS": case "BATSMAN_STYLE_GRAPHICS-OPTIONS": case "RIGHT_GRAPHICS-OPTIONS": case "THISSERIES-STATS_GRAPHICS-OPTIONS":
		case "FF_THISSERIES-STATS_GRAPHICS-OPTIONS": case "L3SEASONPROFILE_GRAPHICS-OPTIONS": case "TICKER_BOWLER_GRAPHICS-OPTIONS":
			return match;
		case "NAMESUPER_GRAPHICS-OPTIONS":
			return new ObjectMapper().writeValueAsString(cricketService.getNameSupers()).toString();
		case "MATCH-PROMO_GRAPHICS-OPTIONS":
		case "PREVIOUS_SUMMARY_GRAPHICS-OPTIONS":
		case "LT-TIEID-DOUBLE_GRAPHICS-OPTIONS":
		case "L3_MATCH-PROMO_GRAPHICS-OPTIONS":
			return new ObjectMapper().writeValueAsString(CricketFunctions.processAllFixtures(cricketService)).toString();
		case "BUG_DB_GRAPHICS-OPTIONS":
			return new ObjectMapper().writeValueAsString(cricketService.getBugs()).toString();
		case "PERFORMANCE_BUG_DB_GRAPHICS-OPTIONS":
			return new ObjectMapper().writeValueAsString(cricketService.getPerformanceBugs()).toString();
		case "PROMPT_GRAPHICS-OPTIONS":
			return new ObjectMapper().writeValueAsString(cricketService.getInfobarStats()).toString();
		case "LEADERBOARD_GRAPHICS-OPTIONS": case "WICKETS_GRAPHICS-OPTIONS":
		case "FOURS_GRAPHICS-OPTIONS": case "SIXES_GRAPHICS-OPTIONS": case "HIGHEST_RUNS_OPTIONS": case "BEST_FIG_OPTIONS":
			List<Tournament> tourn_stats = CricketFunctions.extractTournamentData("CURRENT_MATCH_DATA", false, head_to_head,cricketService, match, past_tournament_stats);
//			List<Tournament> tourn_stats = CricketFunctions.extractTournamentStats("COMBINED_PAST_CURRENT_MATCH_DATA",
//					false, tournament_matches, cricketService, match, null);
			List<BestStats> top_ten_beststats = new ArrayList<BestStats>();
			switch (whatToProcess) {
			case "LEADERBOARD_GRAPHICS-OPTIONS":
				Collections.sort(tourn_stats, new CricketFunctions.BatsmenMostRunComparator());
				break;
			case "WICKETS_GRAPHICS-OPTIONS":
				Collections.sort(tourn_stats, new CricketFunctions.BowlerWicketsComparator());
				break;
			case "FOURS_GRAPHICS-OPTIONS":
				Collections.sort(tourn_stats, new CricketFunctions.BatsmanFoursComparator());
				break;
			case "SIXES_GRAPHICS-OPTIONS":
				Collections.sort(tourn_stats, new CricketFunctions.BatsmanSixesComparator());
				break;
			case "HIGHEST_RUNS_OPTIONS":
				for(Tournament tourn : tourn_stats) {
					for(BestStats bs : tourn.getBatsman_best_Stats()) {
						top_ten_beststats.add(bs);
					}
				}
				
				Collections.sort(top_ten_beststats, new CricketFunctions.PlayerBestStatsComparator());
				return new ObjectMapper().writeValueAsString(top_ten_beststats).toString();
			case "BEST_FIG_OPTIONS":
				for(Tournament tourn : tourn_stats) {
					for(BestStats bs : tourn.getBowler_best_Stats()) {
						top_ten_beststats.add(bs);
					}
				}
				
				Collections.sort(top_ten_beststats, new CricketFunctions.PlayerBestStatsComparator());
				return new ObjectMapper().writeValueAsString(top_ten_beststats).toString();
			}
			return new ObjectMapper().writeValueAsString(tourn_stats).toString();
		}
		
		return null;
	}

