								print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main$All_Fullframes$Side"
										+ which_side
										+ "$BowlingCard$BallExtraData$BallPerformerGrp$AllPerformerData$BottomStatGrp$txt_StatHead"
										+ "*GEOM*TEXT SET " + " " + "\0");
