	public void populateBatsmanstats(PrintWriter print_writer, String viz_scene, int whichInning, String statsType,
			int playerId, MatchAllData match, String broadcaster, int whichside) throws InterruptedException {
		if (match == null) {
			this.status = "ERROR: Match is null";
		} else if (match.getMatch().getInning() == null) {
			this.status = "ERROR: BatsmanStats's inning is null";
		} else {
			int total_inn = 0;

			for (Inning inn : match.getMatch().getInning()) {
				if (inn.getInningStatus() != null) {
					total_inn = total_inn + 1;
				}
			}

			if (total_inn > 0 && whichInning > total_inn) {
				whichInning = total_inn;
			}
//			print_writer.println("-1 RENDERER*TREE*$Main$All_Grp$PositionY$LT$All$Out$PlayerNameGrp$TeamNameGrp$FirstName*GEOM*TEXT SET " + " " + "\0");

//			print_writer.println("-1 RENDERER*TREE*$LT$ALL_LT_LOGOGRP$Select*FUNCTION*Omo*vis_con SET 0 \0");
//			print_writer.println("-1 RENDERER*TREE*$LT$All$BaseAll$Select*FUNCTION*Omo*vis_con SET 5 \0");
//			print_writer.println("-1 RENDERER*TREE*$LT$All$DataAll$Select*FUNCTION*Omo*vis_con SET 12 \0");

			for (Inning inn : match.getMatch().getInning()) {
				if (inn.getInningNumber() == whichInning) {
					String[] Count = CricketFunctions.getScoreTypeData(CricketUtil.BATSMAN, match, whichInning,
							playerId, ",", match.getEventFile().getEvents()).split(",");
					switch (statsType.toUpperCase()) {
					case CricketUtil.BATSMAN:
						for (BattingCard bc : inn.getBattingCard()) {
							if (bc.getPlayerId() == playerId) {
								if (infobar.getLast_which_team() != null && !infobar.getLast_which_team().isEmpty()) {

								} else {
									infobar.setLast_which_team(inn.getBatting_team().getTeamName4());
								}
								print_writer.println("-1 RENDERER*TREE*$LT$ALL_LT_LOGOGRP$Side" + whichside
										+ "$Select$OneTeam$LTLogoGRP$LogoIn$LLC_LogoGrp$img_Badges*TEXTURE*IMAGE SET "
										+ logo_path + inn.getBatting_team().getTeamBadge() + "\0");
								print_writer.println("-1 RENDERER*TREE*$LT$ALL_LT_LOGOGRP$Side" + whichside
										+ "$Select$OneTeam$LTLogoGRP$LogoIn$LLC_LogoGrp$img_Badges_Shadow*TEXTURE*IMAGE SET "
										+ Toutline_color_path + inn.getBatting_team().getTeamBadge() + "\0");

								print_writer.println("-1 RENDERER*TREE*$LT$ALL_LT_LOGOGRP$Side" + whichside
										+ "$Select$OneTeam$LTLogoGRP$LogoIn$LLC_LogoGrp$img_Base2*TEXTURE*IMAGE SET "
										+ base_path + "2/" + inn.getBatting_team().getTeamBadge() + "\0");

								if (bc.getPlayer().getSurname() != null) {
									print_writer.println("-1 RENDERER*TREE*$LT$All$DataAll$Side" + whichside
											+ "$Select$PlayerStats$TopGrp$HeaderGrp$txt_Header1*GEOM*TEXT SET "
											+ bc.getPlayer().getFirstname() + "\0");
									print_writer.println("-1 RENDERER*TREE*$LT$All$DataAll$Side" + whichside
											+ "$Select$PlayerStats$TopGrp$HeaderGrp$txt_Header2*GEOM*TEXT SET "
											+ bc.getPlayer().getSurname() + "\0");
								} else {
									print_writer.println("-1 RENDERER*TREE*$LT$All$DataAll$Side" + whichside
											+ "$Select$PlayerStats$TopGrp$HeaderGrp$txt_Header1*GEOM*TEXT SET "
											+ "" + "\0");
									print_writer.println("-1 RENDERER*TREE*$LT$All$DataAll$Side" + whichside
											+ "$Select$PlayerStats$TopGrp$HeaderGrp$txt_Header2*GEOM*TEXT SET "
											+ bc.getPlayer().getFirstname() + "\0");
								}

								if (bc.getStatus().equalsIgnoreCase(CricketUtil.NOT_OUT)) {
									print_writer.println("-1 RENDERER*TREE*$LT$All$DataAll$Side" + whichside
											+ "$Select$PlayerStats$BottomGrp$ScoreGrp$txt_Data1*GEOM*TEXT SET "
											+ bc.getRuns() + "*" + "\0");
								} else if (bc.getStatus().equalsIgnoreCase(CricketUtil.OUT)) {
									print_writer.println("-1 RENDERER*TREE*$LT$All$DataAll$Side" + whichside
											+ "$Select$PlayerStats$BottomGrp$ScoreGrp$txt_Data1*GEOM*TEXT SET "
											+ bc.getRuns() + "\0");
								}

								print_writer.println("-1 RENDERER*TREE*$LT$All$DataAll$Side" + whichside
										+ "$Select$PlayerStats$BottomGrp$ScoreGrp$txt_Data2*GEOM*TEXT SET "
										+ "OFF " + bc.getBalls() + "\0");

								print_writer.println("-1 RENDERER*TREE*$LT$All$DataAll$Side" + whichside
										+ "$Select$PlayerStats$BottomGrp$RestDataGrp$RestData$Data$1$txt_Data1A*GEOM*TEXT SET "
										+ "DOTS" + "\0");
								print_writer.println("-1 RENDERER*TREE*$LT$All$DataAll$Side" + whichside
										+ "$Select$PlayerStats$BottomGrp$RestDataGrp$RestData$Data$1$txt_Data2A*GEOM*TEXT SET "
										+ Count[0] + "\0");
								print_writer.println("-1 RENDERER*TREE*$LT$All$DataAll$Side" + whichside
										+ "$Select$PlayerStats$BottomGrp$RestDataGrp$RestData$Data$2$txt_Data2A*GEOM*TEXT SET "
										+ bc.getFours() + "\0");
								print_writer.println("-1 RENDERER*TREE*$LT$All$DataAll$Side" + whichside
										+ "$Select$PlayerStats$BottomGrp$RestDataGrp$RestData$Data$3$txt_Data2A*GEOM*TEXT SET "
										+ bc.getSixes() + "\0");
								print_writer.println("-1 RENDERER*TREE*$LT$All$DataAll$Side" + whichside
										+ "$Select$PlayerStats$BottomGrp$RestDataGrp$RestData$Data$4$txt_Data1A*GEOM*TEXT SET "
										+ "S/R" + "\0");
								print_writer.println("-1 RENDERER*TREE*$LT$All$DataAll$Side" + whichside
										+ "$Select$PlayerStats$BottomGrp$RestDataGrp$RestData$Data$4$txt_Data2A*GEOM*TEXT SET "
										+ bc.getStrikeRate() + "\0");
							}
						}
						break;
					}
				}
			}
//			print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene + " C:/Temp/Preview.jpg LT$LTLogoIn 2.000 LT$LTBaseIn 2.000 LT$LTDataIn 2.000\0");
			TimeUnit.MILLISECONDS.sleep(100);
		}
	}

