	public void populateLtMatchPromo(PrintWriter print_writer, String viz_scene, int match_number, List<Team> team,
			List<Fixture> fix, MatchAllData match, String broadcaster) throws InterruptedException {
		if (match == null) {
			this.status = "ERROR: Match is null";
		} else if (match.getMatch().getInning() == null) {
			this.status = "ERROR: MatchId's inning is null";
		} else {
			print_writer.println("-1 RENDERER*TREE*$LT$ALL_LT_LOGOGRP$Side1$Select*FUNCTION*Omo*vis_con SET 1 \0");
			print_writer.println("-1 RENDERER*TREE*$LT$All$BaseAll$Side1$Select*FUNCTION*Omo*vis_con SET 1 \0");
			print_writer.println("-1 RENDERER*TREE*$LT$All$DataAll$Side1$Select*FUNCTION*Omo*vis_con SET 1 \0");

			for (Team TM : team) {
				if (fix.get(match_number - 1).getHometeamid() == TM.getTeamId()) {
					print_writer.println(
							"-1 RENDERER*TREE*$LT$ALL_LT_LOGOGRP$Side1$Select$BothTeam$LTHomeLogoGRP$LogoIn$LLC_LogoGrp$img_Badges*TEXTURE*IMAGE SET "
									+ logo_path + TM.getTeamBadge() + "\0");
					print_writer.println(
							"-1 RENDERER*TREE*$LT$ALL_LT_LOGOGRP$Side1$Select$BothTeam$LTHomeLogoGRP$LogoIn$LLC_LogoGrp$img_Badges_Shadow*TEXTURE*IMAGE SET "
									+ Toutline_color_path + TM.getTeamBadge() + "\0");
					print_writer.println("-1 RENDERER*TREE*$LT$ALL_LT_LOGOGRP$Select$BothTeam$LTHomeLogoGRP$LogoIn$img_Base2*TEXTURE*IMAGE SET " + base_path + "2/" + 
									TM.getTeamBadge() +" \0");
					
					print_writer.println(
							"-1 RENDERER*TREE*$LT$All$DataAll$Side1$Select$MatchId$TopGrp$Home$HeaderGrp$txt_Header1*GEOM*TEXT SET "
									+ TM.getTeamName2().toUpperCase() + "\0");
					print_writer.println(
							"-1 RENDERER*TREE*$LT$All$DataAll$Side1$Select$MatchId$TopGrp$Home$HeaderGrp$txt_Header2*GEOM*TEXT SET "
									+ TM.getTeamName3().toUpperCase() + "\0");
				}
				if (fix.get(match_number - 1).getAwayteamid() == TM.getTeamId()) {
					print_writer.println(
							"-1 RENDERER*TREE*$LT$ALL_LT_LOGOGRP$Side1$Select$BothTeam$LTAwayLogoGRP$LogoIn$LLC_LogoGrp$img_Badges*TEXTURE*IMAGE SET "
									+ logo_path + TM.getTeamBadge() + "\0");
					print_writer.println(
							"-1 RENDERER*TREE*$LT$ALL_LT_LOGOGRP$Side1$Select$BothTeam$LTAwayLogoGRP$LogoIn$LLC_LogoGrp$img_Badges_Shadow*TEXTURE*IMAGE SET "
									+ Toutline_color_path + TM.getTeamBadge() + "\0");
					print_writer.println("-1 RENDERER*TREE*$LT$ALL_LT_LOGOGRP$Select$BothTeam$LTAwayLogoGRP$LogoIn$img_Base2*TEXTURE*IMAGE SET " + base_path + "2/" + 
										TM.getTeamBadge() +" \0");

					print_writer.println(
							"-1 RENDERER*TREE*$LT$All$DataAll$Side1$Select$MatchId$TopGrp$Away$HeaderGrp$txt_Header1*GEOM*TEXT SET "
									+ TM.getTeamName2().toUpperCase() + "\0");
					print_writer.println(
							"-1 RENDERER*TREE*$LT$All$DataAll$Side1$Select$MatchId$TopGrp$Away$HeaderGrp$txt_Header2*GEOM*TEXT SET "
									+ TM.getTeamName3().toUpperCase() + "\0");
				}
			}
			Calendar cal = Calendar.getInstance();
			cal.add(Calendar.DATE, +1);
			if (fix.get(match_number - 1).getDate()
					.equalsIgnoreCase(new SimpleDateFormat("dd-MM-yyyy").format(cal.getTime()))) {

				print_writer.println(
						"-1 RENDERER*TREE*$LT$All$DataAll$Side1$Select$MatchId$BottomGrp$RestDataGrp$txt_Data1*GEOM*TEXT SET "
								+ "TOMORROW - " + fix.get(match_number - 1).getMatchfilename().toUpperCase() + "\0");
				print_writer.println(
						"-1 RENDERER*TREE*$LT$All$DataAll$Side1$Select$MatchId$BottomGrp$RestDataGrp$txt_Data1*GEOM*TEXT SET "
								+ "LIVE FROM " + match.getSetup().getVenueName().toUpperCase() + "\0");

			} else {
				
				print_writer.println(
						"-1 RENDERER*TREE*$LT$All$DataAll$Side1$Select$MatchId$BottomGrp$RestDataGrp$txt_Data1*GEOM*TEXT SET "
								+ "UP NEXT - " + fix.get(match_number - 1).getMatchfilename().toUpperCase() + "\0");
				print_writer.println(
						"-1 RENDERER*TREE*$LT$All$DataAll$Side1$Select$MatchId$BottomGrp$RestDataGrp$txt_Data1*GEOM*TEXT SET "
								+ "LIVE FROM " + match.getSetup().getVenueName().toUpperCase() + "\0");

			}
			
			print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene
					+ " C:/Temp/Preview.png LT$LTBaseIn 1.800 LT$LTLogoIn 1.500 " + "LT$LTDataIn 2.000 \0");
			TimeUnit.SECONDS.sleep(2);
		}
	}

