	public void populateDuckWorthLewisEquation(PrintWriter print_writer, String viz_scene, String balls,
			MatchAllData match, String session_selected_broadcaster) throws InterruptedException {
		switch (session_selected_broadcaster.toUpperCase()) {
		case "DOAD_LLC":
			int runs = 0, total_runs = 0;
			String ahead_behind = "";
			Document htmlFile = null;

			print_writer.println("-1 RENDERER*TREE*$LT$ALL_LT_LOGOGRP$Side1$Select*FUNCTION*Omo*vis_con SET 0 \0");
			print_writer.println("-1 RENDERER*TREE*$LT$All$BaseAll$Side1$Select*FUNCTION*Omo*vis_con SET 5 \0");
			print_writer.println("-1 RENDERER*TREE*$LT$All$DataAll$Side1$Select*FUNCTION*Omo*vis_con SET 17 \0");

//			print_writer.println(
//					"-1 RENDERER*TREE*$LT$All$BaseAll$Side1$Select$OneTeamOption02$LT$Base1$img_Base1*TEXTURE*IMAGE SET "
//							+ base_path + "1/" + match.getMatch().getInning().get(1).getBatting_team().getTeamBadge()
//							+ " \0");
//			print_writer.println(
//					"-1 RENDERER*TREE*$LT$All$BaseAll$Side1$Select$OneTeamOption02$LT$Base2$img_Base2*TEXTURE*IMAGE SET "
//							+ base_path + "2/" + match.getMatch().getInning().get(1).getBatting_team().getTeamBadge()
//							+ " \0");
//
//			print_writer.println(
//					"-1 RENDERER*TREE*$LT$All$DataAll$Side1$Select$Target$TopGrp$HeaderGrp$img_Text2*TEXTURE*IMAGE SET "
//							+ text_path + "2/" + match.getMatch().getInning().get(1).getBatting_team().getTeamBadge()
//							+ "\0");
			print_writer.println(
					"-1 RENDERER*TREE*$LT$ALL_LT_LOGOGRP$Side1$Select$OneTeam$LTLogoGRP$LogoIn$LLC_LogoGrp$img_Base2*TEXTURE*IMAGE SET "
							+ base_path+"2/" + match.getMatch().getInning().get(1).getBatting_team().getTeamBadge() + "\0");
			print_writer.println(
					"-1 RENDERER*TREE*$LT$ALL_LT_LOGOGRP$Side1$Select$OneTeam$LTLogoGRP$LogoIn$LLC_LogoGrp$img_Badges*TEXTURE*IMAGE SET "
							+ logo_path + match.getMatch().getInning().get(1).getBatting_team().getTeamBadge() + "\0");
			print_writer.println(
					"-1 RENDERER*TREE*$LT$ALL_LT_LOGOGRP$Side1$Select$OneTeam$LTLogoGRP$LogoIn$LLC_LogoGrp$img_Badges_Shadow*TEXTURE*IMAGE SET "
							+ logo_path + match.getMatch().getInning().get(1).getBatting_team().getTeamBadge() + "\0");

			print_writer.println(
					"-1 RENDERER*TREE*$LT$All$DataAll$Side1$Select$Target$TopGrp$HeaderGrp$img_Text2$txt_Header1*GEOM*TEXT SET "
							+ match.getMatch().getInning().get(1).getBatting_team().getTeamName1() + "\0");

			try {
				for (Inning inn : match.getMatch().getInning()) {
					if (inn.getIsCurrentInning().toUpperCase().equalsIgnoreCase(CricketUtil.YES)) {
						htmlFile = Jsoup.parse(new File("C:\\Sports\\Cricket\\ParScores BB.html"), "ISO-8859-1");
					}
				}
			} catch (IOException e) {
				e.printStackTrace();
			}
			List<DuckWorthLewis> this_dls = new ArrayList<DuckWorthLewis>();
			for (int i = 14; i < htmlFile.body().getElementsByTag("font").size() - 1; i++) {
				if (htmlFile.body().getElementsByTag("font").get(i).text().contains("TableID")) {
					i = i + 15;
					if (i > htmlFile.body().getElementsByTag("font").size()) {
						break;
					}
				}

				for (Inning inn : match.getMatch().getInning()) {
					if (inn.getIsCurrentInning().toUpperCase().equalsIgnoreCase(CricketUtil.YES)) {
						total_runs = inn.getTotalRuns();
						this_dls.add(new DuckWorthLewis(htmlFile.body().getElementsByTag("font").get(i).text(), htmlFile
								.body().getElementsByTag("font").get(i + (2 + (inn.getTotalWickets()))).text()));
					}
				}
				i = i + 11;

			}
			for (int i = 0; i <= this_dls.size() - 1; i++) {
				if (this_dls.get(i).getOver_left().equalsIgnoreCase(balls)) {
					// System.out.println("RUNS : " + total_runs);
					// System.out.println("RUNS : " +
					// Integer.valueOf((this_dls.get(i).getWkts_down())));
					runs = (total_runs) - Integer.valueOf((this_dls.get(i).getWkts_down()));
					if (runs < 0) {
						ahead_behind = " (" + (Math.abs(runs)) + " runs behind)";
					} else if (runs > 0) {
						ahead_behind = " (" + runs + " runs ahead)";
					} else if (runs == 0) {
						ahead_behind = " (SCORES ARE LEVEL)";
					}

					print_writer.println(
							"-1 RENDERER*TREE*$LT$All$DataAll$Side1$Select$Target$TopGrp$HeaderGrp$txt_Text*GEOM*TEXT SET "
									+ "DLS PAR SCORE AFTER " + balls + " OVERS : "
									+ (Integer.valueOf(this_dls.get(i).getWkts_down())) + ahead_behind.toUpperCase()
									+ "\0");
				}
			}

			print_writer.println(
					"-1 RENDERER PREVIEW SCENE*/Default/LT_All C:/Temp/Preview.png LT$LTBaseIn 1.800 LT$LTLogoIn 1.500 "
							+ "LT$LTDataIn 2.000 \0");
			TimeUnit.MILLISECONDS.sleep(100);
			break;
		}
	}

