	public void checkConditionChange(PrintWriter print_writer, String whatToProcess, List<Scene> scenes,
			String valueToProcess, CricketService cricketService, MatchAllData match) throws InterruptedException {
		if (which_graphic_on_screen == "NAMESUPER-PLAYER") {
			populateNameSuperPlayer(print_writer, previous_data.split(",")[0],
					 previous_data.split(",")[1],
					Integer.valueOf(previous_data.split(",")[2]), cricketService.getAllPlayer(), match, broadcaster, 1);

			ChangeOnGraphic(print_writer, which_graphic_on_screen, "CHANGE_ON", 1, infobar.getWhich_team());

		} else {
			if (infobar.isLt_loaded() != true) {
				scenes.get(1).setScene_path(valueToProcess.split(",")[0]);
				scenes.get(1).scene_load(print_writer, broadcaster);
				// print_writer.println("-1 RENDERER*BACK_LAYER*STAGE SHOW 0.0 \0");

				infobar.setLt_loaded(true);
			}
		}
	}

