	public void populateInfobarPlayerStats(Infobar infobar, boolean is_this_updating, PrintWriter printWriter,
			int teamId, int playerId, String playerType, String Profile, MatchAllData match, Statistics stats,
			String broadcaster) {
		Player plyr = getPlayerFromMatchData(stats.getPlayer_id(), match);
		if (plyr.getTeamId() == match.getSetup().getHomeTeamId()) {
			System.out.println("HOME : " + plyr.getFirstname());
		} else {
			System.out.println("Away : " + plyr.getFirstname());
		}
		switch (playerType.toUpperCase()) {
		case "BAT":
			if (Profile.toUpperCase().equalsIgnoreCase(CricketUtil.DT20)
					|| Profile.toUpperCase().equalsIgnoreCase(CricketUtil.IT20)
					|| Profile.toUpperCase().equalsIgnoreCase(CricketUtil.ODI)
					|| Profile.toUpperCase().equalsIgnoreCase("LLCS1")) {
				System.out
						.println(" stats.getMatches() : " + stats.getMatches() + " stats.Runs() : " + stats.getRuns());

			}
			break;
		}
	}
	
	public void callOtherMethods(PrintWriter print_writer, String whatToProcess, String valueToProcess, MatchAllData match, CricketService cricketService,Configuration config) throws CloneNotSupportedException, InterruptedException {
		switch(whatToProcess.toUpperCase()) {
			case "POPULATE-TOURNAMENT_FOURS":
				populateTournamentFoursPopUp(print_writer, valueToProcess, match, config);
				break;
			case "POPULATE-TOURNAMENT_SIXES": 
				populateTournamentSixesPopUp(print_writer, valueToProcess, match, config);
				break;
			case "POPULATE-THISMATCH_FOURS": 
				populateThisMatchFoursPopUp(print_writer, valueToProcess, match, config);
				break;
			case "POPULATE-THISMATCH_SIXES":
				populateThisMatchSixesPopUp(print_writer, valueToProcess, match, config);
				break;
			case "POPULATE-BAT-POPUP":
				data = valueToProcess;
				if(which_graphic_on_screen == "BAT-POPUP") {
					which_side = 2;
				}else {
					which_side = 1;
				}
				populateBatPopUp(print_writer, valueToProcess.split(",")[0], Integer.valueOf(valueToProcess.split(",")[1]), 
						valueToProcess.split(",")[2],Integer.valueOf(valueToProcess.split(",")[3]), which_side, match,cricketService, broadcaster, config);
				populateEverestPreview(print_writer, valueToProcess.split(",")[0], which_side, "BAT-POPUP");
				break;
			case "POPULATE-BOWL-POPUP":
				data = valueToProcess;
				if(which_graphic_on_screen == "BOWL-POPUP") {
					which_side = 2;
				}else {
					which_side = 1;
				}
				populateBowlPopUp(print_writer, valueToProcess.split(",")[0], Integer.valueOf(valueToProcess.split(",")[1]), 
						valueToProcess.split(",")[2],Integer.valueOf(valueToProcess.split(",")[3]), which_side, match,cricketService, broadcaster, config);
				populateEverestPreview(print_writer, valueToProcess.split(",")[0], which_side, "BOWL-POPUP");
				break;
			case "POPULATE-INNING_SUMMARY":
				populateInningSummary(print_writer, valueToProcess.split(",")[0],
						Integer.valueOf(valueToProcess.split(",")[1]), match, config);
				break;
			case "POPULATE-MANHATTAN":
				populateManhattan(print_writer, valueToProcess.split(",")[0],
						Integer.valueOf(valueToProcess.split(",")[1]), match, broadcaster);
				break;
			case "POPULATE-WORM":
				populateWorm(print_writer, valueToProcess.split(",")[0],
						Integer.valueOf(valueToProcess.split(",")[1]), match, broadcaster,
						match.getEventFile().getEvents());
				break;
		}
	}

